/* Two tables a browser could change or read with the public key (round 32, tenant isolation). `username_history` (an old handle and the one it became, which every old /@link follows) had one policy, "Service role can manage username_history", FOR ALL USING (true) WITH CHECK (true) and no role named, so it applied to everybody: anybody, signed in or not, could add a row for any account, rewrite one or delete one, and so send any old handle's links to a profile of their choosing. That policy goes. Reading stays open to everybody, as it was (the old and new handle is what each redirect already shows). Adding a row stays open to a signed in person for their own account and their own current username only, which is the row Settings writes from the browser just before it saves a new username (components/app/settings-form-new.tsx); changing and deleting rows, and anything at all without signing in, are taken away. The server writes it with its own key (app/api/profile/username), which row level security does not stop. `flow_execution_log` (the older email automation runs, with each recipient's address) never had row level security; it is turned on with no policy and taken from anon and authenticated, since only the server reads or writes it. Either table missing is skipped with a notice. No rows change. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.username_history') IS NULL THEN RAISE NOTICE 'username_history is not there: nothing to lock.'; RETURN; END IF; ALTER TABLE public.username_history ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Service role can manage username_history" ON public.username_history; DROP POLICY IF EXISTS username_history_read ON public.username_history; CREATE POLICY username_history_read ON public.username_history FOR SELECT TO anon, authenticated USING (true); DROP POLICY IF EXISTS username_history_add_own ON public.username_history; CREATE POLICY username_history_add_own ON public.username_history FOR INSERT TO authenticated WITH CHECK (user_id = (SELECT auth.uid()) AND lower(old_username) = lower((SELECT p.username FROM public.profiles p WHERE p.id = (SELECT auth.uid())))); REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.username_history FROM PUBLIC, anon; REVOKE UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.username_history FROM authenticated; END $do$;
DO $do$ BEGIN IF to_regclass('public.flow_execution_log') IS NULL THEN RAISE NOTICE 'flow_execution_log is not there: nothing to lock.'; RETURN; END IF; ALTER TABLE public.flow_execution_log ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.flow_execution_log FROM PUBLIC, anon, authenticated; GRANT ALL ON public.flow_execution_log TO service_role; END $do$;
notify pgrst, 'reload schema';
